/** Accept only the fixed, non-authorizing intent generated by CFL. */
export function isChatLink(value: string | null | undefined): boolean {
  return value === 'etosllmstudio://open/chat';
}

/** Subscribe before reading the launch URL, and ignore callbacks after cleanup. */
export function listenForChatLink(linking: {
  getInitialURL(): Promise<string | null | undefined>;
  addEventListener(type: 'url', listener: (event: { url: string }) => void): { remove(): void };
}, openChat: () => void): () => void {
  let active = true, received = false;
  const subscription = linking.addEventListener('url', event => {
    if (active && isChatLink(event.url)) { received = true; openChat(); }
  });
  void linking.getInitialURL().then(url => { if (active && !received && isChatLink(url)) openChat(); }).catch(() => {});
  return () => { active = false; subscription.remove(); };
}
